def find_order_dfs(num_courses, prerequisites):
    adj = [[] for _ in range(num_courses)]
    for a, b in prerequisites:
        adj[b].append(a)
    state = [0] * num_courses                              # 0=unvisited, 1=in progress, 2=done
    result = []
    def dfs(u):
        if state[u] == 1:
            return False                                        # cycle detected
        if state[u] == 2:
            return True
        state[u] = 1
        for v in adj[u]:
            if not dfs(v):
                return False
        state[u] = 2
        result.append(u)                                          # post-order: append AFTER descendants
        return True
    for i in range(num_courses):
        if not dfs(i):
            return []
    return result[::-1]                                       # reverse the post-order

